package com.personal.meditation;
import static org.junit.Assert.*;import android.content.Context;import android.graphics.*;import android.net.Uri;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class)@Config(sdk=28)@GraphicsMode(GraphicsMode.Mode.NATIVE)public class BackgroundImageTest{
 Context context;
 @Before public void setup(){context=RuntimeEnvironment.getApplication();BackgroundImage.file(context).delete();context.getSharedPreferences("meditation_settings",0).edit().clear().commit();}
 private File image(int width,int height)throws Exception{File file=new File(context.getCacheDir(),"picked-image.png");Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.GREEN);try(FileOutputStream out=new FileOutputStream(file)){assertTrue(bitmap.compress(Bitmap.CompressFormat.PNG,100,out));}finally{bitmap.recycle();}return file;}
 @Test public void pickedImageIsPrivatelyCopiedAndDownsampled()throws Exception{File source=image(2200,800);BackgroundImage.importImage(context,Uri.fromFile(source));assertTrue(BackgroundImage.file(context).isFile());assertNotEquals(source,BackgroundImage.file(context));Bitmap saved=BitmapFactory.decodeFile(BackgroundImage.file(context).getAbsolutePath());try{assertTrue(saved.getWidth()<=2048&&saved.getHeight()<=2048);assertEquals(2200f/800f,(float)saved.getWidth()/saved.getHeight(),.01f);}finally{saved.recycle();}assertTrue(source.delete());assertTrue(BackgroundImage.file(context).length()>0);}
 @Test public void failedImageImportKeepsThePreviousPrivateImage()throws Exception{BackgroundImage.importImage(context,Uri.fromFile(image(40,30)));byte[] previous=java.nio.file.Files.readAllBytes(BackgroundImage.file(context).toPath());File broken=new File(context.getCacheDir(),"broken-image");java.nio.file.Files.write(broken.toPath(),"not an image".getBytes(java.nio.charset.StandardCharsets.UTF_8));try{BackgroundImage.importImage(context,Uri.fromFile(broken));fail();}catch(IOException expected){}assertArrayEquals(previous,java.nio.file.Files.readAllBytes(BackgroundImage.file(context).toPath()));}
 @Test public void imageModeRequiresAStoredImageAndSurvivesSettingsReload()throws Exception{Settings settings=new Settings(context);org.json.JSONObject config=settings.get();config.getJSONObject("appearance").put("imageBackground",true);assertFalse(settings.save(config.toString()));BackgroundImage.importImage(context,Uri.fromFile(image(40,30)));assertTrue(settings.save(config.toString()));org.json.JSONObject saved=new Settings(context).get();assertTrue(saved.getBoolean("backgroundImageAvailable"));assertTrue(saved.getJSONObject("appearance").getBoolean("imageBackground"));assertTrue(saved.getString("backgroundImageUrl").startsWith("https://meditation.local/background?v="));}
}
